Algorithm Mochila
  Define libros, cuadernos As Integer;
  Define nombre As String <- "Leo";
  libros <- 3;
  cuadernos <- libros * 2;
  Write nombre, " lleva ", libros, " libros y ", cuadernos, " cuadernos";
EndAlgorithm

Algorithm Varios
  Define a, b As Integer <- 0;
  Write a;
EndAlgorithm

Algorithm Repetido
  Define x As Integer <- 1;
  Define x As Integer <- 2;
  Write x;
EndAlgorithm
